<template><div ref="viewport" class="canvas-viewport" :class="{preview:previewMode}" @pointerdown.self="$emit('select','')"><div class="canvas-scaler" :style="{width:`${overlay.resolution.width*scale}px`,height:`${overlay.resolution.height*scale}px`}"><div class="overlay-canvas" :style="canvasStyle"><div v-if="!previewMode&&showGrid" class="canvas-grid"></div><template v-if="!previewMode&&showGuides"><div class="safe-guide webcam">Webcam safe area</div><div class="safe-guide chat">Chat safe area</div><div class="safe-guide alerts">Alert safe area</div><div class="safe-guide action">Action safe zone</div></template><div v-for="guide in snapGuides" :key="`${guide.axis}-${guide.value}`" class="snap-guide" :class="guide.axis" :style="guide.axis==='x'?{left:`${guide.value}px`}:{top:`${guide.value}px`}"></div><div v-for="widget in ordered" v-show="widget.enabled" :key="widget.id" class="widget-frame" :class="{selected:widget.id===selectedId,locked:widget.locked,replaying:widget.id===activeWidgetId&&!animationsPaused}" :style="frameStyle(widget)" :tabindex="previewMode?-1:0" :aria-label="`${widget.name}${widget.locked?', locked':''}`" @pointerdown.stop="startMove($event,widget)" @click.stop="$emit('select',widget.id)" @keydown="nudge($event,widget)"><component :is="registry[widget.type].component" :widget="widget"/><template v-if="!previewMode&&widget.id===selectedId&&!widget.locked"><button v-for="handle in handles" :key="handle" class="resize-handle" :class="handle" :aria-label="`Resize ${widget.name} from ${handle}`" @pointerdown.stop="startResize($event,widget,handle)"></button></template><span v-if="!previewMode&&widget.locked" class="lock-badge">Locked</span></div></div></div></div></template>
<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,ref}from'vue';import{widgetRegistry as registry}from'../../overlays/widgetRegistry.js';import{clientDeltaToCanvas,editorScale,moveFrame,resizeFrame}from'../../overlays/overlayGeometry.js'
import { createWidgetSnapshot } from '../../overlays/overlaySnapshots.js'
const props=defineProps({overlay:{type:Object,required:true},selectedId:String,previewMode:Boolean,showPreviewBackground:Boolean,showGuides:Boolean,showGrid:{type:Boolean,default:true},snapping:{type:Boolean,default:true},activeWidgetId:String,animationsPaused:Boolean});const emit=defineEmits(['select','change']);const viewport=ref(null),scale=ref(.45),snapGuides=ref([]),handles=['nw','ne','sw','se'];let observer,interaction=null
const ordered=computed(()=>[...props.overlay.widgets].sort((a,b)=>a.zIndex-b.zIndex));function updateScale(){const b=viewport.value?.getBoundingClientRect();if(b)scale.value=editorScale(props.overlay.resolution.width,props.overlay.resolution.height,Math.max(300,b.width-24),Math.max(220,b.height-24))}onMounted(async()=>{await nextTick();updateScale();observer=new ResizeObserver(updateScale);observer.observe(viewport.value)});onBeforeUnmount(()=>{observer?.disconnect();remove()})
const background=computed(()=>{if(props.overlay.preview.backgroundType==='custom'&&props.overlay.preview.customImageUrl)return`url(${props.overlay.preview.customImageUrl}) center/cover`;if(props.overlay.preview.backgroundType==='solid')return props.overlay.preview.color;const id=props.overlay.preview.referenceAssetId;if(id==='blank')return'#111827';if(id==='bright-gameplay')return'linear-gradient(135deg,#a5c9b7,#4d7183 45%,#a77a4c)';if(id==='camera'||id==='studio')return'radial-gradient(circle at 50% 35%,#425372,#161929 58%,#080b14)';if(id==='minimal')return'linear-gradient(135deg,#171923,#07090e)';return'linear-gradient(145deg,#173b39,#101827 44%,#3b214b)'});const canvasStyle=computed(()=>({width:`${props.overlay.resolution.width}px`,height:`${props.overlay.resolution.height}px`,transform:`scale(${scale.value})`,transformOrigin:'top left',background:props.previewMode&&!props.showPreviewBackground?'transparent':background.value}));function frameStyle(w){return{left:`${w.frame.x}px`,top:`${w.frame.y}px`,width:`${w.frame.width}px`,height:`${w.frame.height}px`,zIndex:w.zIndex}}
function startMove(e,w){emit('select',w.id);if(props.previewMode||w.locked)return;interaction={kind:'move',startX:e.clientX,startY:e.clientY,widget:createWidgetSnapshot(w)};add()}function startResize(e,w,handle){interaction={kind:'resize',handle,startX:e.clientX,startY:e.clientY,widget:createWidgetSnapshot(w)};add()}function add(){window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',end)}function remove(){window.removeEventListener('pointermove',onMove);window.removeEventListener('pointerup',end)}function onMove(e){if(!interaction)return;const d=clientDeltaToCanvas(e.clientX-interaction.startX,e.clientY-interaction.startY,scale.value);let frame;if(interaction.kind==='move'){const moved=moveFrame(interaction.widget.frame,d,props.overlay.resolution,props.overlay.widgets.filter(w=>w.id!==interaction.widget.id).map(w=>w.frame),props.snapping);frame=moved.frame;snapGuides.value=moved.guides}else frame=resizeFrame(interaction.widget.frame,interaction.handle,d,props.overlay.resolution);emit('change',{...interaction.widget,frame},false)}function end(){if(interaction){const w=props.overlay.widgets.find(x=>x.id===interaction.widget.id);if(w)emit('change',createWidgetSnapshot(w),true)}interaction=null;snapGuides.value=[];remove()}function nudge(e,w){if(props.previewMode||w.locked||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const n=e.shiftKey?10:1,d={x:e.key==='ArrowLeft'?-n:e.key==='ArrowRight'?n:0,y:e.key==='ArrowUp'?-n:e.key==='ArrowDown'?n:0};emit('change',{...w,frame:moveFrame(w.frame,d,props.overlay.resolution,[],false).frame},true)}
</script>
